CREATE TABLE IF NOT EXISTS users (id SERIAL PRIMARY KEY, wallet_address VARCHAR(42) UNIQUE NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS transactions (id SERIAL PRIMARY KEY, wallet_address VARCHAR(42) NOT NULL, tx_hash VARCHAR(100) UNIQUE NOT NULL, transaction_type VARCHAR(30) NOT NULL, amount NUMERIC(78,0) NOT NULL, token_address VARCHAR(42), pool_address VARCHAR(42), status VARCHAR(20) DEFAULT 'pending', block_number BIGINT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS deposits (id SERIAL PRIMARY KEY, wallet_address VARCHAR(42) NOT NULL, amount NUMERIC(78,0) NOT NULL, tx_hash VARCHAR(100) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS loans (id SERIAL PRIMARY KEY, wallet_address VARCHAR(42) NOT NULL, borrowed_amount NUMERIC(78,0) DEFAULT 0, repaid_amount NUMERIC(78,0) DEFAULT 0, outstanding_amount NUMERIC(78,0) DEFAULT 0, status VARCHAR(20) DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
